<?php
$uid = (int)$u['id']; $tab = ($_GET['tab'] ?? 'list') === 'ledger' ? 'ledger' : 'list';
$f = ['q' => (string)($_GET['q'] ?? ''), 'type' => (string)($_GET['type'] ?? ''), 'status' => (string)($_GET['status'] ?? ''), 'dir' => (string)($_GET['dir'] ?? ''), 'from' => (string)($_GET['from'] ?? ''), 'to' => (string)($_GET['to'] ?? ''), 'cur' => (string)($_GET['cur'] ?? '')];
$tabs = '<div class="tabs"><a href="' . e(url('activity')) . '"' . ($tab === 'list' ? ' aria-current="page"' : '') . '>All activity</a><a href="' . e(url('activity', ['tab' => 'ledger'])) . '"' . ($tab === 'ledger' ? ' aria-current="page"' : '') . '>Balance explainer</a></div>';
echo page_head('Activity', 'Every transfer, payment, request, group settlement, invoice, bill, refund and escrow movement in one place.', '<a class="btn secondary sm" href="' . e(url('export', ['kind' => 'csv'] + array_filter($f))) . '">' . e(t('Export CSV')) . '</a> <a class="btn secondary sm" href="' . e(url('export', ['kind' => 'pdf'] + array_filter($f))) . '">' . e(t('Export PDF')) . '</a>') . $tabs;
if ($tab === 'ledger') {
  $cur = ($f['cur'] === 'USD') ? 'USD' : 'BDT'; $w = Ledger::wallet($uid, $cur); $es = rows("SELECT e.*, t.ref, t.type, t.status, t.note FROM ledger_entries e JOIN transactions t ON t.id=e.txn_id WHERE e.account_id=? ORDER BY e.id", [$w['account_id']]); $run = 0; $rows = [];
  foreach ($es as $e) { $d = cents($e['amount']) * ($e['direction'] === 'C' ? 1 : -1); $run += $d; $rows[] = [e(fdate($e['created_at'])), ref_link($e['ref']) . '<div class="hint">' . e(type_label($e['type'])) . ' &middot; ' . e($e['phase']) . '</div>', e($e['note']), '<span class="' . ($d < 0 ? 'neg' : 'pos') . '">' . ($d > 0 ? '+' : '') . e(dec($d)) . '</span>', e(dec($run))]; }
  $rows = array_reverse($rows); $sum = Ledger::balanceFromEntries((int)$w['account_id']); $ok = cents($sum) === cents($w['balance']);
  echo '<div class="alert ' . ($ok ? 'ok' : 'err') . '">' . icon($ok ? 'check' : 'alert') . '<div><strong>' . ($ok ? 'Reconciled.' : 'Mismatch!') . '</strong> Sum of ledger entries (' . e($sum) . ') ' . ($ok ? 'equals' : 'does NOT equal') . ' your ' . $cur . ' balance (' . e($w['balance']) . '). Every line below is a double-entry posting: another account is debited or credited by the same amount.</div></div>';
  echo '<form method="get" class="row" style="margin-bottom:12px"><input type="hidden" name="p" value="activity"><input type="hidden" name="tab" value="ledger">' . select('Currency', 'cur', ['BDT' => 'BDT', 'USD' => 'USD'], $cur) . '<div class="fixed field"><label>&nbsp;</label><button class="btn secondary">Show</button></div></form>' . card('Ledger entries for your ' . $cur . ' wallet', tbl(['Date', 'Transaction', 'Note', ['Change', 'num'], ['Running balance', 'num']], $rows, 'No ledger entries yet.')); return;
}
$page = max(1, (int)($_GET['page'] ?? 1)); $per = 20; $total = Activity::count($uid, $f); $items = Activity::fetch($uid, $f, $per, ($page - 1) * $per); $rows = [];
foreach ($items as $t) $rows[] = [e(fdate($t['created_at'])), e(type_label($t['type'])) . '<div class="hint">' . e(Activity::counterparty($t, $uid)) . ($t['note'] ? ' &middot; ' . e(mb_substr($t['note'], 0, 60)) : '') . '</div>', badge($t['status']), ref_link($t['ref']), '<span class="' . ((float)$t['delta'] < 0 ? 'neg' : ((float)$t['delta'] > 0 ? 'pos' : '')) . '">' . ((float)$t['delta'] > 0 ? '+' : '') . e(money($t['delta'], $t['currency'])) . '</span>'];
$types = ['' => 'All'] + array_combine(['topup', 'transfer', 'request_payment', 'merchant_payment', 'settlement', 'iou_repayment', 'invoice_payment', 'bill_payment', 'refund', 'escrow_fund', 'escrow_release', 'escrow_refund', 'conversion', 'pocket_deposit', 'pocket_withdraw', 'rule_transfer', 'round_up', 'offline_payment', 'token_payment'], array_map('type_label', ['topup', 'transfer', 'request_payment', 'merchant_payment', 'settlement', 'iou_repayment', 'invoice_payment', 'bill_payment', 'refund', 'escrow_fund', 'escrow_release', 'escrow_refund', 'conversion', 'pocket_deposit', 'pocket_withdraw', 'rule_transfer', 'round_up', 'offline_payment', 'token_payment']));
$st = ['' => 'All'] + array_combine(['completed', 'held', 'pending', 'cancelled', 'failed', 'refunded', 'disputed'], ['Completed', 'Held', 'Pending', 'Cancelled', 'Failed', 'Refunded', 'Disputed']);
echo card('', '<form method="get"><input type="hidden" name="p" value="activity"><div class="row">' . field('Search', 'q', 'search', $f['q'], 'placeholder="name, note, reference"') . select('Type', 'type', $types, $f['type']) . select('Status', 'status', $st, $f['status']) . select('Direction', 'dir', ['' => 'All', 'in' => 'Money in', 'out' => 'Money out'], $f['dir']) . select('Currency', 'cur', ['' => 'All', 'BDT' => 'BDT', 'USD' => 'USD'], $f['cur']) . field('From', 'from', 'date', $f['from']) . field('To', 'to', 'date', $f['to']) . '<div class="fixed field"><label>&nbsp;</label><button class="btn">' . e(t('Filter')) . '</button></div></div></form>', '', 'flat');
$pages = (int)ceil($total / $per); $pg = ''; if ($pages > 1) { $q = array_filter($f); $pg = '<div class="row" style="margin-top:12px;justify-content:space-between"><span class="muted">' . $total . ' results &middot; page ' . $page . ' of ' . $pages . '</span><span>' . ($page > 1 ? '<a class="btn secondary sm" href="' . e(url('activity', $q + ['page' => $page - 1])) . '">Previous</a> ' : '') . ($page < $pages ? '<a class="btn secondary sm" href="' . e(url('activity', $q + ['page' => $page + 1])) . '">Next</a>' : '') . '</span></div>'; }
echo '<div style="height:16px"></div>' . card('', tbl(['Date', 'Details', 'Status', 'Reference', ['Net effect', 'num']], $rows, 'No transactions match these filters.') . $pg);
